// ---- Mars Life Line style header (generated by scripts/kiln-style-sync.mjs from src/style/tokens.json, style v2) ----
// Paste at the top of every .kiln.js source. Do not edit colours here; edit tokens.json and re-run npm run style:sync.
const PALETTE = {
  'space-deep': 0x20283D,
  'shadow-plum': 0x765768,
  'regolith-mid': 0xB95C40,
  'regolith-light': 0xE6A26A,
  'structure-white': 0xF2E5D2,
  'structure-gray': 0x686976,
  'trim-dark': 0x303240,
  'accent-orange': 0xFF8A24,
  'accent-cyan': 0x54E5F5,
  'accent-blue': 0x35CFFF,
  'glass-tint': 0xEBD9C5,
  'cell-blue': 0x2F58B8,
  'grow-magenta': 0xE040FB,
  'plant-green': 0x5A9E58,
  'ice-pale': 0xD8EEF8
};

const BUDGETS = {"small-prop":1500,"medium-prop":6000,"vehicle":9000,"building":12000,"character":8000,"rock":400};
const SEGMENTS = {"small":8,"default":12,"large":16};

// Bevel radius for roundedBoxGeo: ratio of the smallest dimension (style range 0.06-0.12).
function bevel(w, h, d, ratio = 0.09) {
  return Math.min(w, h, d) * ratio;
}

// One shared material per role. Variants (e.g. structure-gray) take an explicit colour token.
function styleMaterials() {
  const m = {"matte-environment":{"description":"Terrain, rocks, craters, mountains. Fully matte, no reflections.","colors":["regolith-mid","regolith-light","shadow-plum"],"roughness":0.95,"metalness":0},"smooth-structure":{"description":"Buildings, modules, vehicles, suits, crates. Clean satin finish, never mirror-like.","colors":["structure-white","structure-gray"],"roughness":0.55,"metalness":0.05},"accent-paint":{"description":"Non-glowing orange colour blocking: side panels, crate faces, dome base band, suit pads, wheel hubs.","colors":["accent-orange"],"roughness":0.6,"metalness":0},"dark-trim":{"description":"Tyres, recesses, joints, vents.","colors":["trim-dark"],"roughness":0.85,"metalness":0},"emissive-warm":{"description":"Door frames, window strips, headlights. Selected surfaces only.","colors":["accent-orange"],"emissive":"accent-orange","emissiveIntensity":1.6,"roughness":0.5,"metalness":0},"emissive-cool":{"description":"Beacons, indicators, screens. Smaller and rarer than warm lights.","colors":["accent-cyan","accent-blue"],"emissive":"accent-cyan","emissiveIntensity":1.4,"roughness":0.5,"metalness":0},"glass":{"description":"Greenhouse domes, module windows. Light tint, soft highlight, see-through.","colors":["glass-tint"],"roughness":0.15,"metalness":0,"opacity":0.35},"visor":{"description":"Helmet visors and vehicle windshields. Opaque near-black, glossy, shows a soft highlight.","colors":["space-deep"],"roughness":0.12,"metalness":0.1},"solar-cell":{"description":"Solar panel cell faces. Deep blue, semi-gloss, framed by structure-white grid bars.","colors":["cell-blue"],"roughness":0.35,"metalness":0.1}};
  const make = (role, colorToken) => {
    const spec = m[role];
    const color = PALETTE[colorToken ?? spec.colors[0]];
    const name = colorToken && colorToken !== spec.colors[0] ? role + ':' + colorToken : role;
    if (role === 'glass') return glassMaterial(color, { opacity: spec.opacity, roughness: spec.roughness, metalness: spec.metalness, name });
    const opts = { roughness: spec.roughness, metalness: spec.metalness, name };
    if (spec.emissive) Object.assign(opts, { emissive: PALETTE[spec.emissive], emissiveIntensity: spec.emissiveIntensity });
    return gameMaterial(color, opts);
  };
  return {
    rock: make('matte-environment'),
    rockLight: make('matte-environment', 'regolith-light'),
    rockShadow: make('matte-environment', 'shadow-plum'),
    panel: make('smooth-structure'),
    panelGray: make('smooth-structure', 'structure-gray'),
    accent: make('accent-paint'),
    trim: make('dark-trim'),
    glowWarm: make('emissive-warm'),
    glowCool: make('emissive-cool'),
    glowBlue: make('emissive-cool', 'accent-blue'),
    glass: make('glass'),
    visor: make('visor'),
    solarCell: make('solar-cell'),
  };
}
// ---- end style header ----

const meta = {
  name: 'regolith-scoop',
  role: 'prop',
  reference: 'models and assets images/regolith-scoop.webp'
};

async function build() {
  const root = createRoot('regolith-scoop');
  defineBudget({ triangles: BUDGETS['small-prop'] }, root);

  const m = styleMaterials();

  // Dimensions: ~0.26 (X) x 0.32 (Y) x 0.28 (Z) m
  // Ground contact: Y = 0
  const bW = 0.25; // width along Z (left to right)
  const bL = 0.22; // length along X (back to front)
  const bH = 0.095; // basin rim height

  const basinNode = createPivot('basin', [0, 0, 0], root);

  // 1. Scoop Basin Outer Walls (Faceted Tub)
  // Base floor
  const floorGeo = boxGeo(bL * 0.78, 0.02, bW * 0.78);
  createPart('BasinFloor', floorGeo, m.panelGray, {
    parent: basinNode,
    position: [0, 0.01, 0]
  });

  // Tapered lower keel
  const keelFront = boxGeo(0.045, 0.038, bW * 0.74);
  createPart('KeelFront', keelFront, m.panelGray, {
    parent: basinNode,
    position: [bL * 0.38, 0.022, 0],
    rotation: [0, 0, -32]
  });
  const keelBack = boxGeo(0.045, 0.038, bW * 0.74);
  createPart('KeelBack', keelBack, m.panelGray, {
    parent: basinNode,
    position: [-bL * 0.38, 0.022, 0],
    rotation: [0, 0, 32]
  });

  // Basin side walls
  const wallThick = 0.024;
  const wallH = bH - 0.015;

  // Left wall (+Z)
  createPart('WallLeft', boxGeo(bL * 0.76, wallH, wallThick), m.panelGray, {
    parent: basinNode,
    position: [0, 0.02 + wallH * 0.5, bW * 0.5 - wallThick * 0.5]
  });
  // Right wall (-Z)
  createPart('WallRight', boxGeo(bL * 0.76, wallH, wallThick), m.panelGray, {
    parent: basinNode,
    position: [0, 0.02 + wallH * 0.5, -bW * 0.5 + wallThick * 0.5]
  });
  // Back wall (-X)
  createPart('WallBack', boxGeo(wallThick, wallH, bW * 0.76), m.panelGray, {
    parent: basinNode,
    position: [-bL * 0.5 + wallThick * 0.5, 0.02 + wallH * 0.5, 0]
  });
  // Front nose scoop lip (+X)
  const noseL = 0.045;
  createPart('WallFrontNose', boxGeo(noseL, wallH * 0.78, bW * 0.54), m.panelGray, {
    parent: basinNode,
    position: [bL * 0.5 - noseL * 0.5, 0.02 + wallH * 0.39, 0]
  });

  // Front chamfer corners (angling from sides to nose)
  const chamferDiag = Math.hypot(bL * 0.16, bW * 0.20);
  createPart('FrontCornerL', boxGeo(chamferDiag, wallH, wallThick), m.panelGray, {
    parent: basinNode,
    position: [bL * 0.36, 0.02 + wallH * 0.5, bW * 0.36],
    rotation: [0, -42, 0]
  });
  createPart('FrontCornerR', boxGeo(chamferDiag, wallH, wallThick), m.panelGray, {
    parent: basinNode,
    position: [bL * 0.36, 0.02 + wallH * 0.5, -bW * 0.36],
    rotation: [0, 42, 0]
  });

  // Rear chamfer corners
  createPart('BackCornerL', boxGeo(chamferDiag * 0.7, wallH, wallThick), m.panelGray, {
    parent: basinNode,
    position: [-bL * 0.38, 0.02 + wallH * 0.5, bW * 0.36],
    rotation: [0, 45, 0]
  });
  createPart('BackCornerR', boxGeo(chamferDiag * 0.7, wallH, wallThick), m.panelGray, {
    parent: basinNode,
    position: [-bL * 0.38, 0.02 + wallH * 0.5, -bW * 0.36],
    rotation: [0, -45, 0]
  });

  // Front orange lip clip / latch
  const orangeClipGeo = boxGeo(0.016, 0.026, 0.090);
  createPart('FrontOrangeClip', orangeClipGeo, m.accent, {
    parent: basinNode,
    position: [bL * 0.505, bH - 0.016, 0]
  });

  // 2. Regolith Sample Contents inside the basin
  const regolithNode = createPivot('regolith_sample', [0, 0.02, 0], root);

  // Compacted soil bed
  const soilBedGeo = boxGeo(bL * 0.68, 0.030, bW * 0.68);
  createPart('SoilBed', soilBedGeo, m.rock, {
    parent: regolithNode,
    position: [0.01, 0.015, 0]
  });

  // Main center-back large rock clod (faceted 6-sided prism)
  const largeClodGeo = cylinderGeo(0.046, 0.032, 0.055, 6);
  createPart('RockClod_Large', largeClodGeo, m.rock, {
    parent: regolithNode,
    position: [-0.015, 0.052, 0.01],
    rotation: [15, 30, -10]
  });

  // Medium clod front-left
  const medClod1Geo = cylinderGeo(0.032, 0.020, 0.038, 6);
  createPart('RockClod_Med1', medClod1Geo, m.rock, {
    parent: regolithNode,
    position: [0.042, 0.040, 0.042],
    rotation: [-20, 45, 15]
  });

  // Medium clod front-right
  const medClod2Geo = cylinderGeo(0.030, 0.018, 0.034, 5);
  createPart('RockClod_Med2', medClod2Geo, m.rockLight, {
    parent: regolithNode,
    position: [0.038, 0.038, -0.045],
    rotation: [30, -25, 20]
  });

  // Small clods/pebbles
  const smallClodCoords = [
    [-0.05, 0.030, -0.05, 0.018, 0.020],
    [0.055, 0.028, 0.01, 0.016, 0.018],
    [-0.03, 0.028, 0.06, 0.014, 0.016],
    [0.02, 0.032, -0.01, 0.015, 0.015]
  ];
  for (let i = 0; i < smallClodCoords.length; i++) {
    const [cx, cy, cz, cr, ch] = smallClodCoords[i];
    const sGeo = cylinderGeo(cr, cr * 0.7, ch, 5);
    createPart(`RockPebble_${i}`, sGeo, m.rock, {
      parent: regolithNode,
      position: [cx, cy, cz],
      rotation: [i * 25, i * 40, i * 15]
    });
  }

  // 3. Side Pivot Hinges
  const hingeY = 0.075;
  const hingeZ = bW * 0.5 + 0.016; // Z = ±0.141
  const hingeSides = [
    { sign: 1, side: 'L' },
    { sign: -1, side: 'R' }
  ];

  for (const { sign, side } of hingeSides) {
    const hZ = sign * hingeZ;
    const hingeCollar = cylinderGeo(0.028, 0.028, 0.018, 12);
    createPart(`HingeCollar_${side}`, hingeCollar, m.panelGray, {
      parent: root,
      position: [0, hingeY, hZ],
      rotation: [90, 0, 0]
    });

    const hingePin = cylinderGeo(0.016, 0.016, 0.022, 10);
    createPart(`HingePin_${side}`, hingePin, m.accent, {
      parent: root,
      position: [0, hingeY, hZ + sign * 0.003],
      rotation: [90, 0, 0]
    });
  }

  // 4. Arch Frame (Ivory rollbar arching over scoop)
  const archNode = createPivot('arch_frame', [0, 0, 0], root);

  const archLegH = 0.125;
  const archLegGeo = boxGeo(0.032, archLegH, 0.028);

  // Left upright (+Z)
  createPart('ArchLeg_L', archLegGeo, m.panel, {
    parent: archNode,
    position: [0, hingeY + archLegH * 0.5, bW * 0.5 + 0.008]
  });
  // Right upright (-Z)
  createPart('ArchLeg_R', archLegGeo, m.panel, {
    parent: archNode,
    position: [0, hingeY + archLegH * 0.5, -bW * 0.5 - 0.008]
  });

  // Orange accent side panels on outer faces of uprights
  const accentPlateGeo = boxGeo(0.028, 0.075, 0.008);
  createPart('LegAccent_L', accentPlateGeo, m.accent, {
    parent: archNode,
    position: [0, hingeY + 0.07, bW * 0.5 + 0.024]
  });
  createPart('LegAccent_R', accentPlateGeo, m.accent, {
    parent: archNode,
    position: [0, hingeY + 0.07, -bW * 0.5 - 0.024]
  });

  // Shoulder bends (angled elbows in YZ plane: rotation around X!)
  const shoulderGeo = boxGeo(0.032, 0.048, 0.028);
  createPart('ArchShoulder_L', shoulderGeo, m.panel, {
    parent: archNode,
    position: [0, hingeY + archLegH + 0.016, bW * 0.44],
    rotation: [-36, 0, 0] // tilts inward toward center
  });
  createPart('ArchShoulder_R', shoulderGeo, m.panel, {
    parent: archNode,
    position: [0, hingeY + archLegH + 0.016, -bW * 0.44],
    rotation: [36, 0, 0] // tilts inward toward center
  });

  // Top horizontal bridge bar
  const topBridgeY = hingeY + archLegH + 0.035; // ~0.235 m
  const bridgeSpanZ = bW * 0.72;
  const bridgeGeo = boxGeo(0.036, 0.028, bridgeSpanZ);
  createPart('ArchBridge', bridgeGeo, m.panel, {
    parent: archNode,
    position: [0, topBridgeY, 0]
  });

  // 5. Overhead Work Lamp Pod (shining down into scoop)
  const lampNode = createPivot('work_lamp', [0, topBridgeY - 0.014, 0], root);

  // Lamp casing (slate angled pod)
  const lampBodyGeo = boxGeo(0.054, 0.030, 0.084);
  createPart('LampCasing', lampBodyGeo, m.panelGray, {
    parent: lampNode,
    position: [0, -0.015, 0]
  });

  // Downward-facing work light lens (glowing warm)
  const lensGeo = boxGeo(0.042, 0.005, 0.066);
  createPart('LampLens', lensGeo, m.glowWarm, {
    parent: lampNode,
    position: [0, -0.031, 0]
  });

  // Front top cyan status indicator bar
  const indicatorGeo = boxGeo(0.014, 0.005, 0.032);
  createPart('LampIndicator', indicatorGeo, m.glowCool, {
    parent: lampNode,
    position: [0.022, 0.001, 0]
  });

  // 6. Top Carry Handle
  const handleNode = createPivot('handle', [0, topBridgeY + 0.014, 0], root);

  // Handle base sockets
  const socketGeo = boxGeo(0.028, 0.014, 0.028);
  createPart('Socket_L', socketGeo, m.panelGray, {
    parent: handleNode,
    position: [0, 0.007, 0.052]
  });
  createPart('Socket_R', socketGeo, m.panelGray, {
    parent: handleNode,
    position: [0, 0.007, -0.052]
  });

  // Orange handle frame (U-tube grip with angled shoulders)
  const handleLegH = 0.046;
  const handleLegGeo = boxGeo(0.024, handleLegH, 0.024);
  createPart('HandleLeg_L', handleLegGeo, m.accent, {
    parent: handleNode,
    position: [0, 0.014 + handleLegH * 0.5, 0.052]
  });
  createPart('HandleLeg_R', handleLegGeo, m.accent, {
    parent: handleNode,
    position: [0, 0.014 + handleLegH * 0.5, -0.052]
  });

  // Top grip bar
  const gripSpan = 0.128;
  const gripBarGeo = boxGeo(0.026, 0.024, gripSpan);
  createPart('HandleGrip', gripBarGeo, m.accent, {
    parent: handleNode,
    position: [0, 0.014 + handleLegH + 0.012, 0]
  });

  return root;
}
